#!/usr/bin/env bash
# Full existing checks plus actual Changes screenshots; preserve a failing test exit.
set -u
apd_build_number="$1"
apd_test_status=0
timeout --signal=TERM --kill-after=30 1080 ./gradlew :android:connectedDebugAndroidTest -PapdTestBuild "-PapdBuild=C${apd_build_number}" "-Pandroid.testInstrumentationRunnerArguments.class=com.shatteredpixel.shatteredpixeldungeon.android.UimsdRestoreDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.AndroidBackDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.PlayRunDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.RunSetupDifficultyDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.ApdSettingsClickDeviceTest#adultHumorControlWorksWithoutAnAgeProviderAndReopensWithSavedChoice,com.shatteredpixel.shatteredpixeldungeon.android.ApdSettingsClickDeviceTest#grudgeControlsRespondToActualTouches,com.shatteredpixel.shatteredpixeldungeon.android.ApdSettingsClickDeviceTest#communityMenuOpensEveryPreviewAndReturnsWithoutStackingWindows,com.shatteredpixel.shatteredpixeldungeon.android.ApdSettingsClickDeviceTest#categorizedSettingsPreserveControlsAndRespondOnSmallScreens,com.shatteredpixel.shatteredpixeldungeon.android.AboutDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdScreensDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdResourcesDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.ChangesVisualDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.ReleaseNotesNavigationDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.CustomRulesNoticeDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.TopScoresDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.CustomScoreDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.TitleMenuLayoutDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.ClassSaveSlotsDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.PileExaminationDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdSearchDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdColumnsModalDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdChartDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdResearchDeviceTest" || apd_test_status=$?
mkdir -p codex-visual-evidence
for apd_visual_name in apd-settings-categories.png apd-settings-gameplay.png apd-settings-rules.png apd-settings-hotbar.png apd-settings-visibility.png apd-settings-history.png apd-settings-advanced.png apd-settings-narrow.png uimsd-navigation-parent.png uimsd-navigation-child-back.png uimsd-navigation-restored.png uimsd-equipment-window.png uimsd-run-dna.png uimsd-research-evidence.png uimsd-luck-lab.png uimsd-discoveries.png uimsd-investigation.png uimsd-chart-values.png uimsd-chart-counts.png hotbar-controls.png daily-earned-score.png daily-earned-score-scrolled.png custom-scoring-vision.png custom-scoring-vision-narrow.png boss-key-no-promotion.png victory-no-promotion.png options-confirmations.png waterskin-confirm.png known-trap-confirm.png main-title-layout.png main-title-hidden.png main-title-restored.png custom-rules-live-drag.png custom-rules-live-summary.png healing-conversion-setting.png cleric-first-run.png cleric-empty-slot-picker.png cleric-four-slot-touch.png apd-changes.png apd-technical-changes.png release-notes-navigation.png release-notes-reopened.png spd-changes-reference.png apd-build-22.png apd-build-37.png apd-codex-test-67.png tiles-original-2.png tiles-enhanced-2.png tiles-original-4.png tiles-enhanced-4.png stairs-shortcut.png stairs-highlight.png uimsd-empty-home.png uimsd-home.png uimsd-demo-info.png uimsd-text-values.png uimsd-sort-keys.png chalice-preview.png blacksmith-rewards.png blacksmith-reward-detail.png healing-confirmation.png healing-threshold-settings.png metamorph-five-choices.png metamorph-choice-detail.png custom-rules-notice.png custom-rules-notice-narrow.png custom-rules-notice-narrow-scrolled.png custom-rules-equipment.png custom-rules-touch-gestures.png top-scores-main-menu.png top-scores-rankings.png custom-score-neutral.png custom-score-pending.png custom-score-unknown.png custom-score-narrow.png custom-score-narrow-before.png uimsd-saved-question.png; do
    if ! adb exec-out cat "/sdcard/Pictures/APD-Test-Visuals/${apd_visual_name}" > "codex-visual-evidence/${apd_visual_name}"; then
        rm -f "codex-visual-evidence/${apd_visual_name}"
        if [ "$apd_test_status" -eq 0 ]; then apd_test_status=1; fi
    fi
done
if ! python3 tools/validate_android_visuals.py codex-visual-evidence apd-settings-categories.png apd-settings-gameplay.png apd-settings-rules.png apd-settings-hotbar.png apd-settings-visibility.png apd-settings-history.png apd-settings-advanced.png apd-settings-narrow.png uimsd-navigation-parent.png uimsd-navigation-child-back.png uimsd-navigation-restored.png uimsd-equipment-window.png uimsd-run-dna.png uimsd-research-evidence.png uimsd-luck-lab.png uimsd-discoveries.png uimsd-investigation.png uimsd-chart-values.png uimsd-chart-counts.png hotbar-controls.png daily-earned-score.png daily-earned-score-scrolled.png custom-scoring-vision.png custom-scoring-vision-narrow.png boss-key-no-promotion.png victory-no-promotion.png options-confirmations.png waterskin-confirm.png known-trap-confirm.png main-title-layout.png main-title-hidden.png main-title-restored.png custom-rules-live-drag.png custom-rules-live-summary.png healing-conversion-setting.png cleric-first-run.png cleric-empty-slot-picker.png cleric-four-slot-touch.png apd-changes.png apd-technical-changes.png release-notes-navigation.png release-notes-reopened.png spd-changes-reference.png apd-build-22.png apd-build-37.png apd-codex-test-67.png tiles-original-2.png tiles-enhanced-2.png tiles-original-4.png tiles-enhanced-4.png stairs-shortcut.png stairs-highlight.png uimsd-empty-home.png uimsd-home.png uimsd-demo-info.png uimsd-text-values.png uimsd-sort-keys.png chalice-preview.png blacksmith-rewards.png blacksmith-reward-detail.png healing-confirmation.png healing-threshold-settings.png metamorph-five-choices.png metamorph-choice-detail.png custom-rules-notice.png custom-rules-notice-narrow.png custom-rules-notice-narrow-scrolled.png custom-rules-equipment.png custom-rules-touch-gestures.png top-scores-main-menu.png top-scores-rankings.png custom-score-neutral.png custom-score-pending.png custom-score-unknown.png custom-score-narrow.png custom-score-narrow-before.png uimsd-saved-question.png; then apd_test_status=1; fi
exit "$apd_test_status"




